 const cars=Array.from({length:9},(_,i)=>`<g class="cause-car ${i>1?'extra-car':''}" style="--car-delay:-${(i*1.7).toFixed(1)}s;--car-lane:${i%2?205:225}px"><rect x="0" y="-10" width="32" height="15" rx="4" fill="${['#e1d6b5','#8fb4ad','#c6a579'][i%3]}"/><path d="M9-10l5-8h10l5 8" fill="#acc2bd"/><circle cx="8" cy="7" r="4" fill="#4d5c51"/><circle cx="25" cy="7" r="4" fill="#4d5c51"/></g>`).join('');
