export function setupAntecedents({selectStage,openPhoto}){
 const root=document.createElement('div');root.id='antecedents';root.className='antecedents';root.dataset.mode=0;root.innerHTML=`<div class="antecedents-heading"><div><p class="eyebrow">事故前的条件</p><h3>降雨与车流，怎样共同影响边坡？</h3></div><span class="interaction-hint">点选主题 · 动态演示</span></div><div class="cause-facts"><div><b>740.5 <small>mm</small></b><span>灾前一个月累计降雨</span></div><div><b>0.5 <small>km²</small></b><span>北侧集雨面积</span></div><div><b>约 37 万 <small>m³</small></b><span>集雨区累计降雨体积</span></div></div><div class="cause-layout"><div class="cause-visual">${scene()}<div class="cause-animation-controls"><button type="button" id="cause-play" aria-pressed="false">播放演示 ▷</button><span id="cause-play-status"></span><i class="cause-time-track" aria-hidden="true"><b></b></i></div></div><div class="cause-story"><div class="cause-tabs" role="group" aria-label="事故前条件演示主题">${modes.map((m,i)=>`<button type="button" data-cause-mode="${i}" aria-pressed="${i===0}"><small>0${i+1}</small>${m.name}<span>↗</span></button>`).join('')}</div><div class="cause-description" aria-live="polite"><h4 id="cause-title"></h4><p id="cause-text"></p><div class="cause-metric"><strong id="cause-metric"></strong><span id="cause-metric-label"></span></div><p id="cause-mechanism"></p><div id="cause-path"></div></div></div></div><div class="cause-links"><button type="button" class="text-link" id="cause-map">对照图3 · 降雨汇流 ↗</button><button type="button" class="text-link" id="cause-calculation">查看水与荷载叠加工况 →</button></div>`;
 $('#story .facts').after(root);
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let mode=0,wantsPlay=!reduced.matches,inView=false,timer=null;
 function show(i){mode=i;root.dataset.mode=i;root.querySelectorAll('[data-cause-mode]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.causeMode===i)));const m=modes[i];$('#cause-title').textContent=m.title;$('#cause-text').textContent=m.text;$('#cause-mechanism').textContent=m.mechanism;$('#cause-metric').innerHTML=`${m.metric} <small>${m.unit}</small>`;$('#cause-metric-label').textContent=m.label;$('#cause-path').textContent=m.next;sync();}
 function sync(){clearInterval(timer);timer=null;const running=wantsPlay&&inView&&!document.hidden;root.classList.toggle('is-running',running);root.dataset.running=String(running);$('#cause-play').textContent=wantsPlay?'Ⅱ 暂停演示':'▷ 播放演示';$('#cause-play').setAttribute('aria-pressed',String(wantsPlay));$('#cause-play-status').textContent=`${wantsPlay?'自动演示':'已暂停'} · 0${mode+1} / 03`;if(running)timer=setInterval(()=>show((mode+1)%modes.length),6000);}
 root.querySelectorAll('[data-cause-mode]').forEach(b=>b.addEventListener('click',()=>{wantsPlay=false;show(+b.dataset.causeMode);}));$('#cause-play').addEventListener('click',()=>{wantsPlay=!wantsPlay;sync();});$('#cause-map').addEventListener('click',()=>openPhoto('image5.jpeg','图3 · 灾害点降雨汇流图'));$('#cause-calculation').addEventListener('click',()=>{selectStage(3);$('#explore').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
 const observer=new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;sync();},{threshold:.12});observer.observe(root);document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',()=>{wantsPlay=!reduced.matches;sync();});show(0);
}
